from render import render_rows


def export_csv(rows, totals=False):
    if totals and rows:
        # Compute totals for each column
        num_cols = len(rows[0])
        col_sums = [0] * num_cols
        for row in rows:
            for i, val in enumerate(row):
                col_sums[i] += val
        rows = rows + [col_sums]
    return "\n".join(render_rows(rows))

